class Solution:

	def solve(self, i, j, k, a, b, c, dp):
		if i == len(a) and j == len(b) and (k == len(c)):
			return 1
		if dp[i][j] != -1:
			return dp[i][j]
		(ans1, ans2) = (0, 0)
		if i < len(a) and a[i] == c[k]:
			ans1 = self.solve(i + 1, j, k + 1, a, b, c, dp)
		if j < len(b) and b[j] == c[k]:
			ans2 = self.solve(i, j + 1, k + 1, a, b, c, dp)
		dp[i][j] = ans1 + ans2
		return dp[i][j]

	def isInterleave(self, A, B, C):
		j = 0
		i = 0
		k = 0
		dp = [[-1 for i in range(len(B) + 1)] for j in range(len(A) + 1)]
		if len(A) + len(B) != len(C):
			return 0
		return self.solve(i, j, k, A, B, C, dp)
